import logging
import re
import time
from abc import ABC, abstractmethod

from taf.hw.optical_switch.devices.tcp import TCPOpticalSwitch
from taf.hw.optical_switch.exceptions import (
    InvalidInput,
    OpticalSwitchError,
    TooManyRetries,
)


class POLATIS(TCPOpticalSwitch, ABC):
    """
    | Represents POLATIS optical switch
    | Kwargs available in the interface:

    :param str model: Model of the optical switch
    :param str host: Hostname or IP address of the optical switch
    :param int, optional port: Port number of the optical switch *(defaults to 333)*
    :param int, optional timeout: Timeout for the optical switch *(defaults to 10)*
    :param int, optional buffer_size: Size of the buffer for the optical switch *(defaults to 128)*
    :param str, optional decode: Encoding for the optical switch *(defaults to 'utf-8')*
    :param int, optional retry: Number of retries for the optical switch *(defaults to 3)*
    :param int, optional interval: Interval between retries in seconds *(defaults to 1)*
    """

    _COMMAND_END_STRING = "\n"
    _CONNECTION_ADD_COMMAND = ":oxc:swit:conn:add {ports_str}"
    _CONNECTION_GET_COMMAND = ":oxc:swit:conn:stat?"
    _CONNECTION_DISCONNECT_ALL_COMMAND = ":oxc:swit:disc:all"
    _CONNECTION_DISCONNECT_COMMAND = ":oxc:swit:conn:sub {ports_str},{mode}"

    def __init__(self, host, port=333, **kwargs):
        super().__init__(host=host, port=port, **kwargs)
        self._response_errors = [""]

    def get_optical_switch_channels(self):
        """
        Get information which channels are set on which modules

        :raises TooManyRetries(OpticalSwitchConnectionError): Request failed too many times.
        :returns: dictionary with input port as key and output port as value
        """
        msg = self._build_get_optical_switch_channels_command()
        response = self._tcp_client.execute_with_retry(
            msg, self._retry, read=True, stop_msg=b")\r\n"
        )
        self._verify_response(response)
        return self._decode_get_optical_switch_channels_response(response)

    def set_optical_switch_channels(self, new_settings):
        """
        Set channels on modules

        :param dict new_settings: Dictionary with input port as key and output port as value
        :raises TooManyRetries(OpticalSwitchConnectionError): Request failed too many times.
        :raises InvalidInput(OpticalSwitchError): Invalid input data.
        """
        msg = self._build_set_optical_switch_channels_command(new_settings)
        self._tcp_client.execute_with_retry(
            msg, self._retry, read=False, stop_msg=b")\r\n"
        )
        self._check_if_settings_changed(new_settings, self._retry)

    def remove_connections(self, in_ports=[], out_ports=[], force=False):
        """
        Remove connections specified by in and/or out ports.

        If ``force`` is False, then the command will fail if its completion would affect protection switching.

        :param list in_ports: List of input ports to remove connections by
        :param list out_ports: List of output ports to remove connections by
        :param boolean force: Force the removal of the connection
        :raises OpticalSwitchError: Failed to close all of the specified connections
        :raises TooManyRetries(OpticalSwitchConnectionError): Request failed too many times.
        """
        mode = "FORCed" if force else "NORMal"
        if len(in_ports) == 0 and len(out_ports) == 0:
            logging.debug("No ports specified, nothing to do")
            return

        in_ports = self._normalize_ports_list(in_ports)
        out_ports = self._normalize_ports_list(out_ports)

        channels = self.get_optical_switch_channels()
        msg = f"Channels connected before execution:\n{channels}"
        logging.info(msg)

        disconnect_command = self._build_disconnect_command(in_ports, out_ports, mode)
        self._tcp_client.execute_with_retry(
            disconnect_command, self._retry, read=False, stop_msg=b")\r\n"
        )
        self._get_disconnect_result(in_ports, out_ports)

    def remove_all_connections(self):
        """
        Close all active connections

        :raises OpticalSwitchError: Failed to close all of the connections
        :raises TooManyRetries(OpticalSwitchConnectionError): Request failed too many times.
        """
        self._tcp_client.execute_with_retry(
            self._CONNECTION_DISCONNECT_ALL_COMMAND,
            self._retry,
            read=False,
            stop_msg=b")\r\n",
        )
        channels = self.get_optical_switch_channels()
        if len(list(channels.keys())) == 0:
            return
        else:
            raise OpticalSwitchError(
                f"""Failed to close all of the connections.
                Still active connections: \n {channels}"""
            )

    def _build_get_optical_switch_channels_command(self):
        return self._CONNECTION_GET_COMMAND + self._COMMAND_END_STRING

    def _build_set_optical_switch_channels_command(self, optical_connection_settings):
        """
        :param dict optical_connection_settings: delta changes with dict :oxc:swit:conn:add (@1,2,3),(@17,18,19)
        :return command for set switch channels
        """
        new_settings = self._normalize_connection_setting_dict(
            optical_connection_settings
        )
        self._verify_port_settings(new_settings)

        ports_str = self._get_ports_str_by_settings(new_settings)
        return (
            self._CONNECTION_ADD_COMMAND.format(ports_str=ports_str)
            + self._COMMAND_END_STRING
        )

    @staticmethod
    def _normalize_connection_setting_dict(settings):
        """
        normalize connection setting dict
        """
        return {str(input): str(output) for input, output in settings.items()}

    @staticmethod
    def _normalize_ports_list(ports):
        """
        normalize connection setting dict
        """
        return [str(port) for port in ports]

    @staticmethod
    def _get_ports_str_by_settings(settings):
        """
        get command ports str by settings
        :param dict settings: settings
        example
        {'1': '17', '2': '18', '8': '24'}
        :return: string of ports with command format:output
        example
        (@1,2,8),(@17,18,24)-
        """
        keys_str = ",".join(list(settings.keys()))
        values_str = ",".join([settings[k] for k in settings.keys()])
        output_ports_str = f"(@{keys_str}),(@{values_str})"
        return output_ports_str

    def _decode_get_optical_switch_channels_response(self, response):
        """
        decode the response to dict
        :param str response: original response
        example
        (@1,2,8),(@17,18,24)
        :return: dict of input:output
        example
        {'1': '17', '2': '18', '8': '24'}
        """
        pattern = re.compile(r"\(@(\d.*?)\)")
        result = pattern.findall(response)
        if not result:
            return {}

        connection_in_list = result[0].split(",")
        connection_out_list = result[1].split(",")
        return {
            in_port: connection_out_list[index]
            for index, in_port in enumerate(connection_in_list)
        }

    def _verify_port_settings(self, settings):
        """
        :param dict settings: port settings like {'1': '17'}
        verify port settings input and output numbers is valid or not.
        """
        if len(settings.keys()) > self.MAX_PORT_PAIR_NUMBER:
            raise InvalidInput(
                f"'{self.PRODUCT_CODE}' has only {self.MAX_PORT_PAIR_NUMBER} input ports, "
                f"entered {len(settings.keys())} values"
            )

        for in_port, out_port in settings.items():
            in_port = int(in_port)
            out_port = int(out_port)
            if in_port < self.IN_PORT_MIN_NUMBER or in_port > self.IN_PORT_MAX_NUMBER:
                raise InvalidInput(
                    f"""
                    Input port value in '{self.PRODUCT_CODE}' must be between {self.IN_PORT_MIN_NUMBER} and
                    {self.IN_PORT_MAX_NUMBER}. Entered value: {in_port}"""
                )
            if (
                out_port < self.OUT_PORT_MIN_NUMBER
                or out_port > self.OUT_PORT_MAX_NUMBER
            ):
                raise InvalidInput(
                    f"""
                    Output port value in '{self.PRODUCT_CODE}' must be between {self.OUT_PORT_MIN_NUMBER} and
                    less than {self.OUT_PORT_MAX_NUMBER}. Entered value: {out_port}"""
                )

    def _get_disconnect_result(self, in_ports, out_ports):
        channels = self.get_optical_switch_channels()
        in_ports_connected = list(channels.keys())
        out_ports_connected = list(channels.values())
        disconnect_failed_in_ports = [
            port for port in in_ports if port in in_ports_connected
        ]
        disconnect_failed_out_ports = [
            port for port in out_ports if port in out_ports_connected
        ]
        if (
            len(disconnect_failed_in_ports) != 0
            or len(disconnect_failed_out_ports) != 0
        ):
            msg = f"""
            Failed to disconnect some ports:
                In ports: {disconnect_failed_in_ports}
                Out ports: {disconnect_failed_out_ports}
            """
            raise OpticalSwitchError(msg)
        return

    def _build_disconnect_command(self, in_ports, out_ports, mode):
        in_ports_str = ",".join(self._normalize_ports_list(in_ports))
        out_ports_str = ",".join(self._normalize_ports_list(out_ports))
        disconnect_port_str = f"(@{in_ports_str}),(@{out_ports_str})"
        return (
            self._CONNECTION_DISCONNECT_COMMAND.format(
                ports_str=disconnect_port_str, mode=mode
            )
            + self._COMMAND_END_STRING
        )

    def _verify_response(self, response):
        pass

    def _check_if_settings_changed(self, new_settings, retry):

        formated_new_settings = self._normalize_connection_setting_dict(new_settings)
        msg = self._build_get_optical_switch_channels_command()
        curr_tries = 0
        while retry > curr_tries:
            curr_tries += 1
            response = self._tcp_client.execute_with_retry(
                msg, self._retry, read=True, stop_msg=b")\r\n"
            )
            settings = self._decode_get_optical_switch_channels_response(response)
            if all(item in settings.items() for item in formated_new_settings.items()):
                return
            time.sleep(self._interval)
        raise TooManyRetries(
            f"Failed to check whether setting have changed in {retry} attempts"
        )

    @property
    @abstractmethod
    def MAX_PORT_PAIR_NUMBER(self):
        """Amount of port pairs in switch"""
        pass

    @property
    @abstractmethod
    def IN_PORT_MIN_NUMBER(self):
        """First input port number"""
        pass

    @property
    @abstractmethod
    def IN_PORT_MAX_NUMBER(self):
        """Last input port number"""
        pass

    @property
    @abstractmethod
    def OUT_PORT_MIN_NUMBER(self):
        """First output port number"""
        pass

    @property
    @abstractmethod
    def OUT_PORT_MAX_NUMBER(self):
        """Last output port number"""
        pass

    @property
    @abstractmethod
    def PRODUCT_CODE(self):
        pass


class POLATISOXCNOST1616LU1DMHNS(POLATIS):
    _MAX_PORT_PAIR_NUMBER = 16
    _IN_PORT_MIN_NUMBER = 1
    _IN_PORT_MAX_NUMBER = 16
    _OUT_PORT_MIN_NUMBER = 17
    _OUT_PORT_MAX_NUMBER = 32
    PRODUCT_CODE = "N-OST-16x16-LU1-DMHNS"

    @property
    def MAX_PORT_PAIR_NUMBER(self):
        return self._MAX_PORT_PAIR_NUMBER

    @property
    def IN_PORT_MIN_NUMBER(self):
        return self._IN_PORT_MIN_NUMBER

    @property
    def IN_PORT_MAX_NUMBER(self):
        return self._IN_PORT_MAX_NUMBER

    @property
    def OUT_PORT_MIN_NUMBER(self):
        return self._OUT_PORT_MIN_NUMBER

    @property
    def OUT_PORT_MAX_NUMBER(self):
        return self._OUT_PORT_MAX_NUMBER


